package com.autocare.platform.order;

import com.autocare.platform.common.write.WriteIntegrityService.*;
import com.autocare.platform.vehicle.*;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.math.*;
import java.time.*;
import java.time.temporal.ChronoUnit;
import java.util.*;

/** Source-bound reference assessment, never a replacement for inspection or official evidence. */
public class HealthDashboard {
 final ReservationStore db;final HealthPolicies policies;final HealthObservationService observations;final VehiclePlanEvidence evidence;final ArchiveReminderService targets;
 public HealthDashboard(ReservationStore db,HealthPolicies policies,HealthObservationService observations,VehiclePlanEvidence evidence,ArchiveReminderService targets){this.db=db;this.policies=policies;this.observations=observations;this.evidence=evidence;this.targets=targets;}
 Map<String,Object> confirmation(long owner,long vehicle,String metric,boolean lock){var rows=db.jdbc.queryForList("SELECT model_id,policy_version,observation_revision,confirmed,revision FROM health_evidence_confirmation WHERE user_id=? AND vehicle_id=? AND metric=?"+(lock?" FOR UPDATE":""),owner,vehicle,metric);return rows.isEmpty()?null:rows.get(0);}
 boolean confirmed(Map<String,Object> stored,Long model,long policy,int revision){return stored!=null&&stored.get("model_id")!=null&&model!=null&&ReservationStore.number(stored,"model_id")==model&&ReservationStore.number(stored,"policy_version")==policy&&ReservationStore.number(stored,"observation_revision")==revision&&ReservationStore.number(stored,"confirmed")==1;}
 String eligibility(JsonNode observation,JsonNode rule,String metric){if(rule==null)return "POLICY_NOT_SET";try{HealthPolicyInput.rule(rule,metric,policies.today(),false);}catch(RuntimeException e){return "POLICY_INVALID";}if(HealthPolicyInput.date(rule.get("valid_until")).isBefore(policies.today()))return "POLICY_EXPIRED";if(rule.path("applicability").asText().equals("NOT_APPLICABLE"))return "NOT_APPLICABLE";if(!observation.path("status").asText().equals("RECORDED_UNVERIFIED"))return observation.path("status").asText().equals("SOURCE_UNAVAILABLE")?"SOURCE_UNAVAILABLE":"NOT_SET";
  var m=observation.path("measurement");try{new HealthObservationInput(metric,0,(ObjectNode)m,false,"RECORD").validate(policies.today());}catch(RuntimeException e){return "EVIDENCE_INVALID";}if(!HealthPolicyInput.matches(m,rule))return "NOT_COMPARABLE";long age=ChronoUnit.DAYS.between(HealthPolicyInput.date(m.get("measured_on")),policies.today());return age>rule.get("max_age_days").intValue()?"EVIDENCE_EXPIRED":"ELIGIBLE";
 }
 Map<String,Object> trend(VehicleOwner owner,long vehicle,String metric,JsonNode current,JsonNode rule,String eligibility){var out=new LinkedHashMap<String,Object>();out.put("status","NOT_AVAILABLE");out.put("points",List.of());out.put("delta",null);out.put("truncated",false);if(!eligibility.equals("ELIGIBLE"))return out;
  var history=db.mapper.valueToTree(observations.history(owner,vehicle,metric,null,50));var byDay=new TreeMap<String,Map<String,Object>>();var cm=current.get("measurement");byDay.put(cm.get("measured_on").textValue(),point(current));
  for(var row:history.get("list")){if(row.path("corrected").asBoolean())continue;if(row.path("operation").asText().equals("CLEAR")||!eligibility(row,rule,metric).equals("ELIGIBLE")||row.path("measurement").path("measured_on").asText().compareTo(cm.get("measured_on").textValue())>0)break;String date=row.get("measurement").get("measured_on").textValue();byDay.putIfAbsent(date,point(row));}
  var points=new ArrayList<>(byDay.values());out.put("points",points);out.put("truncated",history.get("has_more").booleanValue());out.put("status",points.size()<2?"INSUFFICIENT":"COMPARABLE_UNVERIFIED");if(points.size()>1)out.put("delta",new BigDecimal(points.get(points.size()-1).get("value").toString()).subtract(new BigDecimal(points.get(0).get("value").toString())).stripTrailingZeros().toPlainString());return out;
 }
 Map<String,Object> point(JsonNode row){var m=row.get("measurement");return Map.of("revision",row.get("revision").intValue(),"archive_id",row.get("archive_id").longValue(),"measured_on",m.get("measured_on").textValue(),"value",m.get("value").textValue(),"unit",m.get("unit").textValue());}
 public Map<String,Object> read(VehicleOwner owner,long vehicle){com.autocare.platform.service.ServiceCatalog.validateId(vehicle);return db.reads.execute(tx->{db.owner(owner,false);var snapshot=evidence.evidence(owner,new VehiclePlanEvidence.Request(vehicle,List.of()));var v=db.mapper.valueToTree(snapshot.get("vehicle"));Long model=v.get("model_id").isNull()?null:v.get("model_id").longValue();var raw=db.mapper.valueToTree(snapshot.get("observations")).get("list");var rows=new ArrayList<Map<String,Object>>();var needed=new LinkedHashMap<Long,Map<String,Object>>();boolean complete=true;int sum=0,weights=0;
  for(int i=0;i<HealthObservationInput.METRICS.size();i++){String metric=HealthObservationInput.METRICS.get(i);var observation=raw.get(i);var state=model==null?null:policies.state(model,metric,false);long version=state==null?0:((Number)state.get("version")).longValue();JsonNode rule=state==null?null:(JsonNode)state.get("rule");String eligibility=model==null?"MODEL_UNKNOWN":eligibility(observation,rule,metric);var stored=confirmation(owner.id(),vehicle,metric,false);int confirmRevision=stored==null?0:((Number)stored.get("revision")).intValue();boolean accepted=eligibility.equals("ELIGIBLE")&&confirmed(stored,model,version,observation.get("revision").intValue());String status=eligibility.equals("ELIGIBLE")?(accepted?"REFERENCE_READY":"CONFIRMATION_REQUIRED"):eligibility;Integer score=accepted?HealthPolicyInput.score(observation.get("measurement"),rule):null;
   if(status.equals("REFERENCE_READY")){int weight=rule.get("weight").intValue();weights+=weight;sum+=score*weight;}else if(!status.equals("NOT_APPLICABLE"))complete=false;
   var row=new LinkedHashMap<String,Object>();row.put("metric",metric);row.put("status",status);row.put("rule_version",version);row.put("rule",eligibility.equals("POLICY_INVALID")?null:rule);row.put("observation",observation);row.put("confirmation",Map.of("revision",confirmRevision,"confirmed",accepted));row.put("score",score);row.put("trend",trend(owner,vehicle,metric,observation,rule,eligibility));row.put("action_status","NONE");
   if(rule!=null&&!eligibility.equals("POLICY_INVALID")&&!rule.get("action_project_id").isNull()){row.put("action_status",score==null?"EVIDENCE_UNKNOWN":"NOT_TRIGGERED");if(score!=null&&score<rule.get("action_score_below").intValue()){long project=rule.get("action_project_id").longValue();var projects=db.jdbc.queryForList("SELECT id,project_name,category FROM standard_project WHERE id=? AND status=1 AND is_deleted=0",project);var applied=db.jdbc.queryForList("SELECT verdict,source_reference,version FROM project_model_applicability WHERE project_id=? AND model_id=?",project,model);
    if(projects.isEmpty())row.put("action_status","PROJECT_UNAVAILABLE");else if(applied.isEmpty()||applied.get(0).get("verdict")==null)row.put("action_status","APPLICABILITY_UNKNOWN");else if(!applied.get(0).get("verdict").equals("APPLICABLE"))row.put("action_status","CONFLICTING_APPLICABILITY");else{row.put("action_status","TRIGGERED");var item=needed.computeIfAbsent(project,id->{var n=new LinkedHashMap<String,Object>();n.put("project_id",id);n.put("project_name",projects.get(0).get("project_name"));n.put("category",projects.get(0).get("category"));n.put("tier","MUST");n.put("evidence",new ArrayList<Map<String,Object>>());return n;});@SuppressWarnings("unchecked")var sources=(List<Map<String,Object>>)item.get("evidence");var m=observation.get("measurement");sources.add(Map.of("metric",metric,"policy_version",version,"observation_revision",observation.get("revision").intValue(),"confirmation_revision",confirmRevision,"action_rule_version",applied.get(0).get("version"),"value",m.get("value").textValue(),"unit",m.get("unit").textValue(),"measured_on",m.get("measured_on").textValue(),"source_reference",rule.get("source_reference").textValue(),"project_source_reference",applied.get(0).get("source_reference")));}
   }}rows.add(row);
  }
  var overall=new LinkedHashMap<String,Object>();boolean ready=complete&&weights>0;overall.put("status",ready?"REFERENCE_READY":"UNKNOWN");overall.put("score",ready?BigDecimal.valueOf(sum).divide(BigDecimal.valueOf(weights),0,RoundingMode.HALF_UP).intValue():null);overall.put("weighted_sum",ready?sum:null);overall.put("weight_total",ready?weights:null);
  var out=new LinkedHashMap<String,Object>();out.put("vehicle",snapshot.get("vehicle"));out.put("today",policies.today().toString());out.put("overall",overall);out.put("metrics",rows);out.put("required_projects",new ArrayList<>(needed.values()));out.put("reminders",reminders(owner,vehicle));out.put("preference",preference(owner,vehicle,false));return out;
 });}
 static JsonNode confirmationInput(String raw){var b=PublicReviewTextInput.parse(raw);PublicReviewTextInput.fields(b,"expected_revision","confirmed","observation_revision","policy_version");HealthPolicyInput.integer(b.get("expected_revision"),0,Integer.MAX_VALUE-1);HealthPolicyInput.integer(b.get("observation_revision"),0,Integer.MAX_VALUE);PublicReviewTextInput.version(b.get("policy_version"));if(!b.get("confirmed").isBoolean())throw ReservationInput.bad();return b;}
 public JsonNode confirm(VehicleOwner owner,long vehicle,String metric,String key,JsonNode raw){HealthObservationInput.metric(metric);var b=confirmationInput(raw.toString());final Long[] model={null};return db.writes.execute(new Actor("user",owner.id()),"PUT","/api/vehicle/"+vehicle+"/health/"+metric+"/confirmation",key,b,()->{db.owner(owner,true);var v=db.one("SELECT model_id FROM vehicle WHERE id=? AND user_id=? AND is_deleted=0 FOR UPDATE",vehicle,owner.id());model[0]=v.get("model_id")==null?null:ReservationStore.number(v,"model_id");if(b.get("confirmed").booleanValue()&&model[0]!=null)policies.model(model[0],true);db.jdbc.queryForList("SELECT id FROM vehicle_health_observation WHERE user_id=? AND vehicle_id=? AND metric=? AND is_deleted=0 FOR UPDATE",owner.id(),vehicle,metric);
  if(b.get("confirmed").booleanValue()){var state=model[0]==null?null:policies.state(model[0],metric,true);var current=db.mapper.valueToTree(observations.list(owner,vehicle)).get("list").get(HealthObservationInput.METRICS.indexOf(metric));if(state==null||((Number)state.get("version")).longValue()!=b.get("policy_version").longValue()||current.get("revision").intValue()!=b.get("observation_revision").intValue()||!eligibility(current,(JsonNode)state.get("rule"),metric).equals("ELIGIBLE"))throw HealthPolicies.conflict();}
 },()->{var before=confirmation(owner.id(),vehicle,metric,true);int revision=before==null?0:((Number)before.get("revision")).intValue();if(revision!=b.get("expected_revision").intValue())throw HealthPolicies.conflict();db.jdbc.update("INSERT INTO health_evidence_confirmation(user_id,vehicle_id,metric,model_id,policy_version,observation_revision,confirmed,revision) VALUES(?,?,?,?,?,?,?,1) ON DUPLICATE KEY UPDATE model_id=VALUES(model_id),policy_version=VALUES(policy_version),observation_revision=VALUES(observation_revision),confirmed=VALUES(confirmed),revision=revision+1",owner.id(),vehicle,metric,model[0],b.get("policy_version").longValue(),b.get("observation_revision").intValue(),b.get("confirmed").booleanValue()?1:0);var after=confirmation(owner.id(),vehicle,metric,true);return new Change("HEALTH_EVIDENCE_CONFIRM","vehicle",vehicle,before==null?Map.of():before,after,Map.of("vehicle_id",vehicle,"metric",metric,"revision",revision+1));});}
 Map<String,Object> preference(VehicleOwner owner,long vehicle,boolean lock){var rows=db.jdbc.queryForList("SELECT maintenance_days,maintenance_km,insurance_days,inspection_days,maintenance_project_id,revision FROM vehicle_reminder_preference WHERE user_id=? AND vehicle_id=?"+(lock?" FOR UPDATE":""),owner.id(),vehicle);if(!rows.isEmpty())return rows.get(0);var out=new LinkedHashMap<String,Object>(Map.of("maintenance_days",0,"maintenance_km",0,"insurance_days",0,"inspection_days",0,"revision",0));out.put("maintenance_project_id",null);return out;}
 static JsonNode preferenceInput(String raw){var b=PublicReviewTextInput.parse(raw);if(b.has("maintenance_project_id"))PublicReviewTextInput.fields(b,"expected_revision","maintenance_days","maintenance_km","insurance_days","inspection_days","maintenance_project_id");else PublicReviewTextInput.fields(b,"expected_revision","maintenance_days","maintenance_km","insurance_days","inspection_days");HealthPolicyInput.integer(b.get("expected_revision"),0,Integer.MAX_VALUE-1);for(String k:List.of("maintenance_days","insurance_days","inspection_days"))HealthPolicyInput.integer(b.get(k),0,365);HealthPolicyInput.integer(b.get("maintenance_km"),0,100000);if(b.hasNonNull("maintenance_project_id"))ReservationInput.id(b.get("maintenance_project_id"));return b;}
 public JsonNode savePreference(VehicleOwner owner,long vehicle,String key,JsonNode raw){var b=preferenceInput(raw.toString());Long project=b.hasNonNull("maintenance_project_id")?b.get("maintenance_project_id").longValue():null;return db.writes.execute(new Actor("user",owner.id()),"PUT","/api/vehicle/"+vehicle+"/reminder-preference",key,b,()->{db.owner(owner,true);db.one("SELECT id FROM vehicle WHERE id=? AND user_id=? AND is_deleted=0 FOR UPDATE",vehicle,owner.id());if(project!=null)db.one("SELECT id FROM standard_project WHERE id=? AND status=1 AND is_deleted=0 FOR UPDATE",project);},()->{var before=preference(owner,vehicle,true);int revision=((Number)before.get("revision")).intValue();if(revision!=b.get("expected_revision").intValue())throw HealthPolicies.conflict();db.jdbc.update("INSERT INTO vehicle_reminder_preference(user_id,vehicle_id,maintenance_days,maintenance_km,insurance_days,inspection_days,maintenance_project_id,revision) VALUES(?,?,?,?,?,?,?,1) ON DUPLICATE KEY UPDATE maintenance_days=VALUES(maintenance_days),maintenance_km=VALUES(maintenance_km),insurance_days=VALUES(insurance_days),inspection_days=VALUES(inspection_days),maintenance_project_id=VALUES(maintenance_project_id),revision=revision+1",owner.id(),vehicle,b.get("maintenance_days").intValue(),b.get("maintenance_km").intValue(),b.get("insurance_days").intValue(),b.get("inspection_days").intValue(),project);var after=preference(owner,vehicle,true);return new Change("REMINDER_PREFERENCE_SET","vehicle",vehicle,before,after,after);});}
 static final List<String> KINDS=List.of("FAULT","MAINTENANCE","INSURANCE","INSPECTION","VIOLATION");
 Map<String,Object> alert(String kind,String severity,String title,long archive,int revision,String reference,int prefRevision){var a=new LinkedHashMap<String,Object>();a.put("kind",kind);a.put("severity",severity);a.put("title",title);a.put("archive_id",archive);a.put("source_revision",revision);a.put("source_reference",reference);a.put("remaining_days",null);a.put("remaining_km",null);a.put("preference_revision",prefRevision);a.put("action",Map.of("type","ARCHIVE","archive_id",archive));return a;}
 List<Map<String,Object>> reminders(VehicleOwner owner,long vehicle){var groups=new LinkedHashMap<String,Map<String,Object>>();for(String k:KINDS){var g=new LinkedHashMap<String,Object>();g.put("kind",k);g.put("status","NOT_SET");g.put("items",new ArrayList<Map<String,Object>>());g.put("limited",false);groups.put(k,g);}var pref=preference(owner,vehicle,false);int prefRevision=((Number)pref.get("revision")).intValue();var planned=db.mapper.valueToTree(targets.list(owner,vehicle));
  for(var target:planned.get("list")){int type=target.get("archive_type").intValue();String kind=type==1?"MAINTENANCE":type==3?"INSURANCE":"INSPECTION";var g=groups.get(kind);String state=target.get("status").textValue();g.put("status",state);if(!Set.of("DUE","PLANNED","UNKNOWN").contains(state))continue;Long days=target.get("due_date").isNull()?null:ChronoUnit.DAYS.between(policies.today(),LocalDate.parse(target.get("due_date").textValue()));Long km=target.get("due_mileage").isNull()||planned.get("current_mileage").isNull()?null:target.get("due_mileage").longValue()-planned.get("current_mileage").longValue();int lead=((Number)pref.get(type==1?"maintenance_days":type==3?"insurance_days":"inspection_days")).intValue();boolean due=days!=null&&days<=0||km!=null&&km<=0;boolean soon=days!=null&&days>0&&days<=lead||type==1&&km!=null&&km>0&&km<=((Number)pref.get("maintenance_km")).intValue();if(due||soon){g.put("status",due?"DUE":"UPCOMING");var a=alert(kind,due?"DUE":"UPCOMING",kind.equals("MAINTENANCE")?"本人保养目标":kind.equals("INSURANCE")?"本人保险目标":"本人年检目标",target.get("archive_id").longValue(),target.get("revision").intValue(),"本人主动设置的来源目标",prefRevision);a.put("remaining_days",days);a.put("remaining_km",km);a.put("action",Map.of("type","TARGET","archive_id",target.get("archive_id").longValue()));if(type==1){if(pref.get("maintenance_project_id")==null)a.put("action",Map.of("type","SERVICES"));else{long project=((Number)pref.get("maintenance_project_id")).longValue();var rows=db.jdbc.queryForList("SELECT p.id FROM standard_project p WHERE p.id=? AND p.status=1 AND p.is_deleted=0 AND NOT EXISTS(SELECT 1 FROM project_model_applicability a JOIN vehicle v ON v.model_id=a.model_id WHERE v.id=? AND a.project_id=p.id AND a.verdict='NOT_APPLICABLE')",project,vehicle);a.put("action",rows.isEmpty()?Map.of("type","SERVICES"):Map.of("type","PROJECT","project_id",project));}}items(g).add(a);}}
  for(int type:List.of(10,6)){String kind=type==10?"FAULT":"VIOLATION";var g=groups.get(kind);var records=db.jdbc.queryForList("SELECT a.id,a.vehicle_id AS source_vehicle,a.is_deleted,a.input_type,a.archive_type AS source_type,d.revision,d.fields_json FROM archive_structured_detail d JOIN vehicle_archive a ON a.id=d.archive_id WHERE d.user_id=? AND d.vehicle_id=? AND d.archive_type=? ORDER BY a.recorded_at DESC,a.id DESC LIMIT 201",owner.id(),vehicle,type);g.put("limited",records.size()>200);boolean unknown=records.size()>200;var seen=new HashSet<String>();int known=0;for(var record:records.subList(0,Math.min(records.size(),200))){var f=db.parse(record.get("fields_json"));String code=f.path(type==10?"fault_code":"case_number").asText("");if(code.isBlank()){unknown=true;continue;}if(!seen.add(type==10?code.toUpperCase(Locale.ROOT):code))continue;if(ReservationStore.number(record,"is_deleted")!=0||ReservationStore.number(record,"source_vehicle")!=vehicle||ReservationStore.number(record,"source_type")!=type||!Set.of(1L,3L).contains(ReservationStore.number(record,"input_type"))){unknown=true;continue;}try{if(!f.isObject())throw ReservationInput.bad();new ArchiveStructuredInput(((Number)record.get("revision")).intValue(),(ObjectNode)f).validateFor(type);if(!f.path("owner_confirmed").asBoolean())throw ReservationInput.bad();}catch(RuntimeException invalid){unknown=true;continue;}String status=f.path(type==10?"fault_status":"violation_status").asText();if(status.equals("UNKNOWN")){unknown=true;continue;}known++;if(type==10?status.equals("ACTIVE"):status.equals("PENDING")){String severity=type==10&&f.path("attention_level").asText().equals("URGENT")?"OWNER_URGENT":"PENDING";String title=type==10?"本人故障记录 "+code+" · "+f.path("fault_description").asText():"本人记录待处理 "+code+" · "+f.path("description").asText();items(g).add(alert(kind,severity,title,((Number)record.get("id")).longValue(),((Number)record.get("revision")).intValue(),f.path("source_reference").asText(),prefRevision));}}
   g.put("status",!items(g).isEmpty()?"ATTENTION":unknown?"UNCONFIRMED":known>0?"CLEAR":"NOT_SET");
  }
  for(var g:groups.values())items(g).sort(Comparator.comparingInt((Map<String,Object> a)->switch(a.get("severity").toString()){case "OWNER_URGENT"->0;case "DUE"->1;case "PENDING"->2;default->3;}).thenComparingLong(a->((Number)a.get("archive_id")).longValue()));return new ArrayList<>(groups.values());
 }
 @SuppressWarnings("unchecked")static List<Map<String,Object>> items(Map<String,Object> group){return (List<Map<String,Object>>)group.get("items");}
}
